/* Home: the gold-and-glass etagere (design D), fitted to the visitor's screen width. */
(function () {
  var W = window, D = document;
  W.SGHome = function (root) {
    var wrap = D.createElement('main'); wrap.className = 'sg-home'; wrap.id = 'sg-main';
    var inner = D.createElement('div'); inner.className = 'sg-home-in'; wrap.appendChild(inner);
    root.appendChild(wrap);
    var mode = null, app = null;
    function fit() {
      var w = D.documentElement.clientWidth, mob = w <= 760, base = mob ? 390 : 1440;
      var m = mob ? 'HomeM' : 'HomeD';
      if (m !== mode) {
        mode = m; inner.innerHTML = '';
        var src = {}; src[m] = W.SG_SRC[m];
        app = W.SGDC.mount(inner, src, m);
      }
      var s = Math.min(w / base, mob ? 1.15 : 1);
      inner.style.width = base + 'px';
      inner.style.zoom = s;
      wrap.classList.toggle('wide', !mob && w > base);
    }
    fit();
    var t; W.addEventListener('resize', function () { clearTimeout(t); t = setTimeout(fit, 150); });
    return wrap;
  };
})();

