    save: function () { try { localStorage.setItem(KEY, JSON.stringify({ items: this.items, wrap: this.wrap })); } catch (e) {} this.emit(); },
    emit: function () { this.fns.forEach(function (f) { try { f(); } catch (e) {} }); },
